class _PhaseRecorder:
    """R14 exclusive bounded slots; no new thread, lock, permission or IPC.

    Positions contain only prebound integer code IDs and line numbers. Unknown
    frames are counted/omitted without filesystem probes or payload inspection.
    """
    BOOTSTRAP_PHASES={**{'BOOTSTRAP_%d_%s'%(i,b):(i,b)for i in range(1,7)for b in ('ENTER','RETURN')},
                      'BOOTSTRAP_COMPLETE':(0,'COMPLETE')}
    PHASES = frozenset(['CHECKPOINT_ENTER', 'CHECKPOINT_RETURN', 'EXECUTOR_CHECK_ENTER', 'EXECUTOR_CHECK_RETURN', 'GRAPH_STREAM_ENTER', 'GRAPH_STREAM_RETURN', 'GUARD_INSTALLED', 'LOW_LEVEL_CHECK_ENTER', 'LOW_LEVEL_CHECK_RETURN', 'MODEL_ENTER', 'MODEL_RETURN', 'PROTOCOL_ENTER', 'PROTOCOL_RETURN', 'ROLE_ENTER', 'ROLE_RETURN', 'SOURCE_ENTER', 'SOURCE_RETURN', 'THREAD_CHECK_ENTER', 'THREAD_CHECK_RETURN', 'THREAD_WAIT_ENTER', 'THREAD_WAIT_RETURN', 'WORKER_ENTER', 'WORKER_RETURN', 'WORKFLOW_ENTER', 'WORKFLOW_RETURN', 'WORK_ITEM_ENTER', 'WORK_ITEM_RETURN'])
    def __init__(self, packet):
        self.counts = {}; self.available = self.binding_ok = self.capture_failed = False
        self.source_identity=packet.get('source_identity')
        self.keys = {}; self.events = {}
        self.root = Path(packet['attempt_root']) / 'evidence/phase_diag.r07'
        try:
            for ancestor in reversed((self.root.parent, *self.root.parent.parents)):
                info = ancestor.lstat()
                if not stat.S_ISDIR(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
                    raise ValueError('DIAG_ANCESTOR_INVALID')
            self.root.mkdir(exist_ok=False)
            self.available = True
            rows = json.loads(Path(packet['pins']['sources']['path']).read_bytes())['rows']
            indexed = {str(Path(row['path']).absolute()).replace('\\', '/').casefold(): row for row in rows}
            roots = {'base': Path(packet['pins']['base_python']['path']).parent,
                     'site': Path(packet['site_root']), 'project': Path(packet['pins']['native_entry']['path']).parents[3]}
            for code_id, kind, relative, function, first, sha, events in _PHASE_SPECS:
                filename = str(roots[kind] / relative).replace('\\', '/').casefold()
                if indexed.get(filename, {}).get('sha256') != sha:
                    raise ValueError('DIAG_SOURCE_BINDING_MISMATCH')
                key = (filename, function, first)
                self.keys[key] = code_id
                for event, phase in events:
                    self.events[(*key, event)] = phase
            self.binding_ok = True
        except BaseException:
            self.capture_failed = True

        # Negative-only dispatch index over the exact installed event map.
        # This contains no source-check result and grants no permission. Keep
        # partial maps on binding failure; index failure uses original lookup.
        try:
            self._event_coordinates=frozenset((function,first,event)for _,function,first,event in self.events)
        except BaseException:
            self._event_coordinates=None
            self.capture_failed=True

    def _take(self, name):
        if name not in self.PHASES and name not in self.BOOTSTRAP_PHASES:
            self.capture_failed = True
            return None
        count = self.counts.get(name, 0) + 1
        if name in self.BOOTSTRAP_PHASES:
            self.counts[name]=min(count,2)
            return (0,1) if count==1 else None
        self.counts[name] = min(count, 1001 if name == 'SOURCE_ENTER' else 5)
        if name == 'SOURCE_ENTER':
            return ((1, 10, 100, 1000).index(count), count) if count in (1, 10, 100, 1000) else None
        return (count - 1, count) if count <= 4 else None

    def _write(self, name, slot, count, frame, elapsed_ns=0):
        if not self.available:
            return
        handle = None
        try:
            positions = []; omitted = 0; cursor = frame
            if self.binding_ok:
                for _ in range(32):
                    if cursor is None:
                        break
                    code = cursor.f_code
                    key = (code.co_filename.replace('\\', '/').casefold(), code.co_name, code.co_firstlineno)
                    code_id = self.keys.get(key)
                    if code_id is not None and len(positions) < 8:
                        positions.append([code_id, cursor.f_lineno])
                    else:
                        omitted += 1
                    cursor = cursor.f_back
            record={'schema': 'TA_BOUND_PHASE_7', 'phase': name, 'slot': slot, 'count': count,
                'monotonic_ns': _phase_time.monotonic_ns(), 'thread': _phase_thread.get_ident(),
                'positions': positions, 'omitted': omitted, 'binding_ok': self.binding_ok,
                'source_elapsed_ns': elapsed_ns}
            if name in self.BOOTSTRAP_PHASES:
                if (type(self.source_identity)is not str or len(self.source_identity)!=64
                        or any(c not in '0123456789abcdef'for c in self.source_identity)):
                    raise ValueError('DIAG_BOOTSTRAP_SOURCE_IDENTITY_INVALID')
                module_id,boundary=self.BOOTSTRAP_PHASES[name]
                record={'schema':'TA_BOOTSTRAP_BOUNDARY_20','phase':name,'module_id':module_id,
                        'boundary':boundary,'slot':0,'count':1,'monotonic_ns':record['monotonic_ns'],
                        'process_time_ns':_phase_time.process_time_ns(),'source_identity':self.source_identity,
                        'binding_ok':self.binding_ok}
            raw = json.dumps(record,sort_keys=True,separators=(',', ':'),allow_nan=False).encode()
            if len(raw) > 512:
                raise ValueError('DIAG_RECORD_LIMIT')
            target = self.root / (name + '.%d.json' % slot)
            handle = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, 'O_BINARY', 0) | getattr(os, 'O_NOINHERIT', 0), 0o600)
            info = os.fstat(handle)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or os.write(handle, raw) != len(raw):
                raise ValueError('DIAG_FILE_WRITE_FAILED')
        except BaseException:
            self.capture_failed = True
        finally:
            if handle is not None:
                try:
                    os.close(handle)
                except BaseException:
                    self.capture_failed = True

    def emit(self, name, frame=None):
        try:
            selected = self._take(name)
            if selected is not None:
                self._write(name, *selected, frame)
        except BaseException:
            self.capture_failed = True

    def source_enter(self, frame):
        try:
            selected = self._take('SOURCE_ENTER')
            if selected is not None:
                started = _phase_time.monotonic_ns()
                self._write('SOURCE_ENTER', *selected, frame)
                return (*selected, started)
        except BaseException:
            self.capture_failed = True
        return None

    def source_return(self, frame, token):
        try:
            slot, count, started = token
            self._write('SOURCE_RETURN', slot, count, frame, max(0, _phase_time.monotonic_ns() - started))
        except BaseException:
            self.capture_failed = True

    def observe(self, frame, event):
        try:
            if event not in {'call','return'}:return
            code = frame.f_code
            filename=code.co_filename
            if (type(filename)is str and self._event_coordinates is not None
                    and (code.co_name,code.co_firstlineno,event)not in self._event_coordinates):return
            key = (filename.replace('\\', '/').casefold(), code.co_name, code.co_firstlineno, event)
            name = self.events.get(key)
            if name is not None:
                self.emit(name, frame)
        except BaseException:
            self.capture_failed = True
